INSERT INTO `doj_cases` (`case_number`, `title`, `description`, `case_type`, `status`, `priority`, `assigned_detective`, `assigned_prosecutor`, `defendant_identifier`, `defendant_name`, `created_by`) VALUES
('2025-CR-0001', 'State vs. Marcus Thompson - Armed Robbery', 'Armed robbery at Fleeca Bank on Route 68. Suspect entered with a firearm, threatened employees, and fled with approximately $45,000 in cash. Getaway vehicle was a black Sultan RS.', 'criminal', 'under_investigation', 'high', 'char5:2222222222', 'char7:4444444444', 'char1:1234567890', 'Marcus Thompson', 'system'),
('2025-CR-0002', 'State vs. Jessica Williams - Drug Trafficking', 'Large scale drug trafficking operation discovered at La Mesa warehouse. Suspect allegedly distributed methamphetamine across Los Santos County. Seized 50kg of controlled substances.', 'criminal', 'pending_trial', 'urgent', 'char5:2222222222', 'char7:4444444444', 'char8:5555555555', 'Jessica Williams', 'system'),
('2025-CR-0003', 'State vs. Derek Sullivan - Grand Theft Auto', 'Suspect linked to theft of 12 vehicles from Premium Deluxe Motorsport over 3 month period. Vehicles valued at over $2.5 million. Chop shop operation suspected.', 'criminal', 'open', 'high', 'char5:2222222222', NULL, 'char9:6666666666', 'Derek Sullivan', 'system'),
('2025-CR-0004', 'State vs. Anthony Morales - First Degree Murder', 'Homicide investigation at Del Perro Pier. Victim identified as Robert Chen, 34. Suspect allegedly had prior altercation with victim. Murder weapon recovered at scene.', 'criminal', 'pending_trial', 'urgent', 'char5:2222222222', 'char7:4444444444', 'char10:7777777777', 'Anthony Morales', 'system'),
('2025-CV-0001', 'Rodriguez vs. LS Transit Authority - Personal Injury', 'Civil suit filed after bus accident on Vinewood Boulevard. Plaintiff claims negligent driving by transit employee caused significant injuries requiring hospitalization.', 'civil', 'pending_trial', 'medium', NULL, NULL, NULL, 'LS Transit Authority', 'system'),
('2025-CV-0002', 'Chen Family vs. Maze Bank - Wrongful Foreclosure', 'Plaintiffs allege wrongful foreclosure on family home in Rockford Hills despite payments being current. Seeking damages and property restoration.', 'civil', 'open', 'medium', NULL, NULL, NULL, 'Maze Bank', 'system'),
('2025-TR-0001', 'State vs. Kevin Park - DUI & Reckless Driving', 'Suspect arrested for DUI after high-speed chase on Del Perro Freeway. BAC recorded at 0.18. Suspect crashed into median barrier. No other injuries reported.', 'traffic', 'closed', 'low', NULL, NULL, 'char11:8888888888', 'Kevin Park', 'system'),
('2025-TR-0002', 'State vs. Sarah Mitchell - Vehicular Manslaughter', 'Fatal accident on Great Ocean Highway. Suspect allegedly ran red light striking pedestrian. Victim pronounced dead at scene. Toxicology pending.', 'traffic', 'under_investigation', 'high', 'char5:2222222222', 'char7:4444444444', 'char12:9999999999', 'Sarah Mitchell', 'system'),
('2025-AD-0001', 'License Revocation - Tommy Nguyen', 'Administrative hearing for license revocation following multiple DUI offenses. Third offense in 24 months. Mandatory minimum suspension applies.', 'administrative', 'pending_trial', 'low', NULL, NULL, 'char13:1010101010', 'Tommy Nguyen', 'system'),
('2025-CR-0005', 'State vs. Unknown - Paleto Bank Heist', 'Major heist at Blaine County Savings Bank. Four masked suspects entered, disabled security, and escaped with $1.2 million. Investigation ongoing.', 'criminal', 'under_investigation', 'urgent', 'char5:2222222222', NULL, NULL, 'Unknown Suspects', 'system');
