INSERT INTO `doj_reports` (`report_number`, `case_id`, `report_type`, `title`, `content`, `narrative`, `location`, `incident_date`, `officer_identifier`, `author_identifier`, `author_name`, `officer_name`, `status`) VALUES
('RPT-2025-0001', 1, 'incident', 'Fleeca Bank Armed Robbery - Initial Response', 'Responded to 211 in progress at Fleeca Bank, Route 68. Upon arrival, suspect had fled scene. Bank employees reported single male suspect, approximately 6ft, medium build, wearing black hoodie and ski mask. Suspect brandished what appeared to be a black semi-automatic handgun. Demanded cash from tellers. Fled northbound in black 4-door sedan. Approximate take: $45,000.', 'At approximately 1423 hours, I was dispatched to a 211 in progress at Fleeca Bank on Route 68. Upon arrival at 1431 hours, I observed multiple civilians outside the bank in distress. Bank manager Lisa Chen informed me that a single male suspect had entered the bank approximately 8 minutes prior, brandished a firearm, and demanded money from the tellers. The suspect was described as approximately 6 feet tall, medium build, wearing a black hoodie and black ski mask. Witness statements indicate the suspect spoke with a local accent and appeared nervous. Security footage has been preserved and forwarded to detectives. Total amount stolen confirmed by bank manager as $45,237.00. No injuries reported.', 'Fleeca Bank, Route 68, Blaine County', '2025-01-15 14:23:00', 'char4:1111111111', 'char4:1111111111', 'Officer Maria Rodriguez', 'Officer Maria Rodriguez', 'approved'),
('RPT-2025-0002', 1, 'investigation', 'Fleeca Robbery - Vehicle Identification', 'Through review of traffic cameras and witness statements, getaway vehicle identified as 2019 Sultan RS, black, plate 5MRT892. Vehicle registered to Marcus Thompson, DOB 03/15/1992. Thompson has prior arrests for assault and possession. BOLO issued.', 'Following initial incident report, I conducted extensive review of traffic camera footage from Route 68 corridor. At timestamp 14:32:47, black Sultan RS observed traveling northbound at high rate of speed. Partial plate captured: 5MR****. Cross-reference with DMV database produced 3 possible matches. Further review of footage from Route 1 intersection captured full plate: 5MRT892. Vehicle registered to Marcus Thompson of 1542 Grove Street, Los Santos. Background check reveals prior arrests: Assault (2018, charges dropped), Possession of controlled substance (2020, 6 months probation). Known associates include members of Families street gang. BOLO issued to all units. Warrant request submitted.', 'Traffic Camera Analysis - Route 68', '2025-01-16 09:00:00', 'char5:2222222222', 'char5:2222222222', 'Detective David Chen', 'Detective David Chen', 'approved'),
('RPT-2025-0003', 2, 'investigation', 'La Mesa Warehouse Drug Bust - Operation Clean Sweep', 'Executed search warrant at 2847 La Mesa Blvd. Discovered large-scale methamphetamine distribution operation. Seized approximately 50kg of methamphetamine, $230,000 cash, multiple firearms. Arrested Jessica Williams on scene.', 'At 0600 hours, tactical team executed search warrant #2025-SW-0042 at 2847 La Mesa Blvd. Entry was made through front and rear doors simultaneously. Suspect Jessica Williams was located in the office area and taken into custody without incident. Search of premises revealed: (1) 50.3kg methamphetamine, street value approximately $1.5 million, (2) $230,450 cash in various denominations, (3) 3 handguns - Glock 19, Beretta 92FS, Smith & Wesson M&P, (4) 1 AR-15 rifle with illegal modifications, (5) Digital scales, packaging materials, and distribution ledgers. Forensic team collected over 200 pieces of evidence. Williams was read Miranda rights and declined to speak without attorney. Ledgers indicate distribution network spanning Los Santos County.', '2847 La Mesa Blvd, Los Santos', '2025-01-10 06:00:00', 'char5:2222222222', 'char5:2222222222', 'Detective David Chen', 'Detective David Chen', 'approved'),
('RPT-2025-0004', 4, 'incident', 'Del Perro Pier Homicide - Initial Response', 'Responded to report of shots fired at Del Perro Pier. Located male victim, later identified as Robert Chen, 34, deceased from apparent gunshot wound. Witness reported verbal altercation prior to shooting.', 'At 2147 hours, responded to multiple 911 calls reporting shots fired at Del Perro Pier near the ferris wheel. Upon arrival at 2153 hours, I located a male victim lying on the wooden boardwalk with apparent gunshot wound to chest. Victim was unresponsive. EMS arrived at 2158 hours and pronounced victim deceased at scene. Victim identified through wallet as Robert Chen, DOB 03/19/1990, of 567 Hawick Ave. Multiple witnesses present. Witness Amanda Brooks stated she observed verbal altercation between victim and another male approximately 5 minutes before shots were heard. Described suspect as Hispanic male, approximately 6\'2", muscular build, wearing gray t-shirt and jeans. Area secured and crime scene tape established. Forensics notified.', 'Del Perro Pier, Los Santos', '2025-01-20 21:47:00', 'char4:1111111111', 'char4:1111111111', 'Officer Maria Rodriguez', 'Officer Maria Rodriguez', 'approved'),
('RPT-2025-0005', 4, 'forensic', 'Del Perro Homicide - Forensic Analysis Report', 'Comprehensive forensic analysis of Del Perro Pier crime scene. Ballistics confirm 9mm round. Shell casing matched to firearm recovered from suspect vehicle.', 'Crime Scene Analysis Report - Case 2025-CR-0004\n\nScene Processing: Crime scene processed from 2200-0400 hours. 47 evidence markers placed. Full photographic documentation completed.\n\nBallistics: Single 9mm shell casing recovered 8 feet from victim. Round recovered from victim during autopsy. Ballistic comparison confirms match - both from same firearm. Subsequent search of suspect vehicle (Schafter V12, plate 8PLT567) recovered Glock 17 9mm under driver seat. Test fire confirms this is the murder weapon.\n\nBiological Evidence: Blood pooling consistent with victim position. No other blood types detected at scene. Trace blood evidence found in trunk of suspect vehicle - DNA match to victim Robert Chen.\n\nFingerprints: Latent prints recovered from nearby railing. Two prints matched to suspect Anthony Morales (prior military record on file).\n\nConclusion: Physical evidence strongly supports charges against Anthony Morales for the murder of Robert Chen.', 'LSPD Crime Lab / Del Perro Pier', '2025-01-22 16:00:00', 'char19:1717171717', 'char19:1717171717', 'Nicole Turner', 'Nicole Turner', 'approved'),
('RPT-2025-0006', 7, 'incident', 'DUI Traffic Stop - Kevin Park', 'Traffic stop for erratic driving on Del Perro Freeway. Driver exhibited signs of intoxication. Field sobriety tests failed. BAC 0.18. Arrested for DUI.', 'At 0213 hours, observed blue Blista (plate 4RTY789) traveling westbound on Del Perro Freeway at approximately 85mph in 65mph zone, weaving between lanes. Initiated traffic stop. Driver identified as Kevin Park, DOB 05/14/1998. Observed: slurred speech, odor of alcohol, bloodshot eyes. Driver admitted to consuming "a few beers" at a party. Field sobriety tests administered: Horizontal Gaze Nystagmus - failed, Walk and Turn - failed, One Leg Stand - failed. Preliminary breath test: 0.18 BAC. Driver arrested for DUI. Vehicle impounded. During pursuit of safe location to stop, driver struck median barrier causing minor front-end damage. No injuries. Driver transported to Mission Row for booking.', 'Del Perro Freeway, Los Santos', '2025-01-08 02:13:00', 'char4:1111111111', 'char4:1111111111', 'Officer Maria Rodriguez', 'Officer Maria Rodriguez', 'approved'),
('RPT-2025-0007', 8, 'incident', 'Fatal Pedestrian Accident - Great Ocean Highway', 'Vehicle versus pedestrian accident with fatality. Driver Sarah Mitchell struck pedestrian in crosswalk. Victim pronounced dead at scene.', 'At 1845 hours, responded to report of vehicle vs. pedestrian accident on Great Ocean Highway at Chumash intersection. Upon arrival, observed white Oracle XS (plate 6YUI234) stopped in roadway with heavy front-end damage. Adult male pedestrian located approximately 40 feet from crosswalk, unresponsive. EMS pronounced victim deceased at 1858 hours. Victim later identified as Harold Foster, 67, local resident. Driver Sarah Mitchell, DOB 10/03/1985, stated she did not see the pedestrian. Witness in following vehicle states victim was in crosswalk when struck. Traffic signal was green for pedestrian. No obvious signs of impairment observed in driver. Blood draw obtained per department policy. Vehicle impounded for forensic examination. Accident reconstruction team notified.', 'Great Ocean Highway at Chumash, Blaine County', '2025-01-18 18:45:00', 'char21:1919191919', 'char21:1919191919', 'Deputy William Torres', 'Deputy William Torres', 'approved'),
('RPT-2025-0008', 3, 'investigation', 'GTA Ring Investigation - Chop Shop Discovery', 'Anonymous tip led to discovery of chop shop operation in El Burro Heights. Multiple stolen vehicles recovered. Investigation ongoing.', 'Following anonymous Crime Stoppers tip, conducted surveillance on warehouse at 1847 El Burro Heights Industrial Park. Over 72-hour period, observed multiple high-end vehicles entering but not exiting. Obtained search warrant #2025-SW-0056. Upon execution, discovered active chop shop operation. Recovered: (1) Osiris - partially stripped, plate matches STOLEN3 from Premium Deluxe case, (2) Unidentified vehicle parts consistent with reported stolen vehicles, (3) VIN removal equipment, (4) Computer with inventory records. No suspects on premises at time of raid. Records indicate operation connected to larger network. Forensic analysis of computer ongoing. Derek Sullivan identified as person of interest through financial records showing payments to warehouse.', '1847 El Burro Heights Industrial Park', '2025-01-25 08:00:00', 'char5:2222222222', 'char5:2222222222', 'Detective David Chen', 'Detective David Chen', 'submitted'),
('RPT-2025-0009', 5, 'civil', 'LS Transit Accident Investigation', 'Investigation into bus accident on Vinewood Boulevard. Multiple witness statements obtained. Maintenance records subpoenaed.', 'Civil Investigation Report - Rodriguez vs. LS Transit Authority\n\nIncident Summary: On 12/15/2024, LS Transit bus #4472 struck vehicle operated by Elena Rodriguez at Vinewood Blvd and Alta St intersection. Ms. Rodriguez sustained multiple injuries requiring hospitalization.\n\nWitness Statements: Three witnesses confirm bus ran red light. Traffic camera footage obtained - confirms bus entered intersection after signal change.\n\nBus Operator: Driver Thomas Wright, employed 12 years, clean record. Post-accident drug test negative. Claims signal was yellow upon entry.\n\nVehicle Inspection: Bus maintenance records show deferred brake maintenance. Last inspection 47 days overdue at time of accident.\n\nConclusion: Evidence suggests contributory negligence by LS Transit Authority for both operator error and maintenance deficiency.', 'Vinewood Blvd & Alta St, Los Santos', '2024-12-15 14:30:00', 'char23:2121212121', 'char23:2121212121', 'Detective Robert Kim', 'Detective Robert Kim', 'approved'),
('RPT-2025-0010', 10, 'investigation', 'Paleto Bank Heist - Initial Investigation', 'Major heist at Blaine County Savings Bank. Four suspects, professional operation. Investigation initiated.', 'At approximately 1030 hours, four masked suspects entered Blaine County Savings Bank in Paleto Bay. Suspects were organized and methodical. Suspect 1 controlled the lobby, Suspects 2 and 3 accessed the vault using thermal lance equipment, Suspect 4 remained at getaway vehicle. Total time inside bank: 12 minutes. Escaped with approximately $1.2 million in cash and contents of 40+ safety deposit boxes. Getaway vehicle: white Rumpo van, no plates, found abandoned and burned 3 miles away. No usable forensic evidence recovered from van. Bank security system was professionally disabled - suggests inside knowledge or extensive reconnaissance. FBI notified due to amount. Reviewing all bank employees and recent large account holders as potential sources of inside information.', 'Blaine County Savings Bank, Paleto Bay', '2025-01-22 10:30:00', 'char5:2222222222', 'char5:2222222222', 'Detective David Chen', 'Detective David Chen', 'submitted');
