INSERT INTO `doj_announcements` (`title`, `content`, `priority`, `author_identifier`, `author_name`, `target_audience`, `expires_at`) VALUES
('BOLO: Marcus Thompson - Armed Robbery Suspect', 'Be on the lookout for Marcus Thompson, wanted for armed robbery. Subject is considered armed and dangerous. Last seen in Grove Street area. Black male, 5\'10", medium build. Do not approach alone. Contact Detective Chen with any information.', 'urgent', 'char5:2222222222', 'Detective David Chen', '["all"]', DATE_ADD(NOW(), INTERVAL 30 DAY)),
('New Evidence Submission Protocol', 'Effective immediately, all physical evidence must be logged into the digital system within 2 hours of collection. Chain of custody forms must be completed in full. See updated SOP document in shared drive.', 'high', 'char24:2222222220', 'Sergeant Patricia Martinez', '["officers", "detectives"]', DATE_ADD(NOW(), INTERVAL 90 DAY)),
('Court Schedule - Week of Feb 3rd', 'Multiple high-profile hearings scheduled. Courtroom A: Thompson arraignment (Mon), Williams preliminary (Fri). Courtroom B: Chen vs Maze Bank motion (Wed). All officers involved in these cases should be available for testimony.', 'medium', 'char6:3333333333', 'Judge Sarah Williams', '["all"]', DATE_ADD(NOW(), INTERVAL 7 DAY)),
('Training: Active Shooter Response', 'Mandatory active shooter response training scheduled for all personnel. Sessions: Feb 10th, 15th, 20th at LSPD Academy. Sign up through department portal. Certification required for field duty.', 'medium', 'char24:2222222220', 'Sergeant Patricia Martinez', '["officers"]', DATE_ADD(NOW(), INTERVAL 30 DAY)),
('IT System Maintenance - Feb 8th', 'MDT system will undergo scheduled maintenance on February 8th from 0200-0600 hours. Limited functionality expected. Emergency dispatch will not be affected. Report any issues to IT department.', 'low', 'system', 'IT Department', '["all"]', DATE_ADD(NOW(), INTERVAL 10 DAY)),
('Welcome New Team Members', 'Please welcome our newest DOJ members: Jennifer Adams (Court Clerk) and Deputy William Torres (transferred from Sandy Shores). Stop by and introduce yourselves!', 'low', 'char24:2222222220', 'Sergeant Patricia Martinez', '["all"]', DATE_ADD(NOW(), INTERVAL 14 DAY));
INSERT INTO `doj_inspections` (`inspection_type`, `subject_identifier`, `subject_name`, `vehicle_plate`, `location`, `officer_identifier`, `officer_name`, `reason`, `findings`, `items_confiscated`, `violations`, `citations_issued`, `arrest_made`, `related_report_id`) VALUES
('traffic_stop', 'char1:1234567890', 'Marcus Thompson', '5MRT892', 'Grove Street & Davis Ave', 'char4:1111111111', 'Officer Maria Rodriguez', 'Speeding - 55 in 35 zone', 'Driver cooperative. License valid. Registration current. No warrants at time of stop (prior to robbery).', NULL, '["speeding"]', '["CIT-2024-8834"]', FALSE, NULL),
('traffic_stop', 'char11:8888888888', 'Kevin Park', '4RTY789', 'Del Perro Freeway', 'char4:1111111111', 'Officer Maria Rodriguez', 'Erratic driving, suspected DUI', 'Failed field sobriety tests. BAC 0.18. Driver arrested.', NULL, '["dui", "speeding", "reckless_driving"]', '["CIT-2025-0012"]', TRUE, 6),
('vehicle_inspection', NULL, NULL, '5MRT892', 'LSPD Impound Lot', 'char19:1717171717', 'Nicole Turner', 'Evidence processing - Fleeca robbery', 'GPS tracker data recovered. Fingerprints matched to suspect. Trace evidence collected from interior.', '["gps_unit", "clothing_fibers", "receipt_from_gas_station"]', NULL, NULL, FALSE, NULL),
('search', 'char8:5555555555', 'Jessica Williams', NULL, '2847 La Mesa Blvd', 'char5:2222222222', 'Detective David Chen', 'Search warrant execution - drug investigation', 'Large quantity of narcotics discovered. Distribution operation confirmed.', '["methamphetamine_50kg", "cash_230450", "glock_19", "beretta_92fs", "sw_mp", "ar15_modified"]', '["drug_trafficking", "illegal_weapons"]', NULL, TRUE, 3),
('frisk', 'char16:1414141414', 'Carlos Mendez', NULL, 'Rancho Projects', 'char21:1919191919', 'Deputy William Torres', 'Parole check - routine contact', 'Subject compliant. No contraband found. Confirmed residence address.', NULL, NULL, NULL, FALSE, NULL),
('property_inspection', NULL, NULL, NULL, '1847 El Burro Heights Industrial Park', 'char5:2222222222', 'Detective David Chen', 'Search warrant execution - chop shop investigation', 'Active chop shop discovered. Multiple stolen vehicle parts. VIN removal equipment.', '["vehicle_parts", "vin_removal_tools", "computer_equipment", "inventory_records"]', '["receiving_stolen_property", "vehicle_tampering"]', NULL, FALSE, 8),
('traffic_stop', 'char18:1616161616', 'Victor Petrov', '9VIP999', 'Great Ocean Highway', 'char4:1111111111', 'Officer Maria Rodriguez', 'Broken tail light', 'Warning issued. Driver cooperative but evasive about travel plans. Note: Person of interest in Paleto heist.', NULL, '["equipment_violation"]', NULL, FALSE, NULL);
